class PerformanceCurveCanvas:public juce::Component {
 SynthProcessor& p;int kind=0,last=-1;std::array<std::array<juce::RangedAudioParameter*,16>,2> parameters{};bool editing=false;
 juce::Rectangle<float> plot()const{return {0,16,(float)getWidth(),(float)getHeight()-16};}
 void end(){if(editing)for(auto* parameter:parameters[kind])parameter->endChangeGesture();editing=false;last=-1;}
 void draw(juce::Point<float> at){auto r=plot();int index=juce::jlimit(0,15,juce::roundToInt(at.x/r.getWidth()*15));float value=juce::jlimit(0.f,1.f,(r.getBottom()-at.y)/r.getHeight());float before=last>=0?parameters[kind][last]->getValue():value;for(int i=juce::jmin(last<0?index:last,index);i<=juce::jmax(last<0?index:last,index);++i){float t=last<0||last==index?1.f:(i-last)/(float)(index-last);parameters[kind][i]->setValueNotifyingHost(before+(value-before)*t);}last=index;repaint();}
public:
 PerformanceCurveCanvas(SynthProcessor& processor):p(processor){setComponentID("performance-curve");for(int k=0;k<2;++k)for(int i=0;i<16;++i)parameters[k][i]=p.state.getParameter(juce::String(k==0?"velocityCurve":"noteCurve")+juce::String(i+1));setMouseCursor(juce::MouseCursor::CrosshairCursor);}
 ~PerformanceCurveCanvas()override{end();}
 void setKind(int next){end();kind=next;repaint();}
 int getKind()const{return kind;}
 void reset(int preset){end();for(int i=0;i<16;++i){auto* parameter=parameters[kind][i];parameter->beginChangeGesture();parameter->setValueNotifyingHost(preset==1?1-i/15.f:preset==2?.5f:i/15.f);parameter->endChangeGesture();}repaint();}
 void paint(juce::Graphics& g)override{using namespace juce;g.fillAll(nd::colour(Colour(0xff0c1620)));auto r=plot();UiStyle::plot(g,r);Path curve;std::array<float,16> points;for(int i=0;i<16;++i)points[i]=parameters[kind][i]->getValue();for(int i=0;i<16;++i){Point<float> point(i/15.f*r.getWidth(),r.getBottom()-points[i]*r.getHeight());if(i==0)curve.startNewSubPath(point);else curve.lineTo(point);}UiStyle::fillCurve(g,curve,r,r.getBottom());g.setColour(UiStyle::blue());g.strokePath(curve,PathStrokeType(1.5f));for(int i=0;i<16;i+=5){float x=i/15.f*r.getWidth(),y=r.getBottom()-points[i]*r.getHeight();g.fillEllipse(x-2,y-2,4,4);}float input=kind==0?p.lastVelocity.load():p.lastNote.load();float value=performanceCurve(points,input);g.setColour(Colours::white.withAlpha(.8f));g.drawVerticalLine(roundToInt(input*r.getWidth()),r.getY(),r.getBottom());g.fillEllipse(input*r.getWidth()-2.5f,r.getBottom()-value*r.getHeight()-2.5f,5,5);g.setFont(FontOptions(8.f,Font::bold));g.setColour(UiStyle::blue());g.drawText(kind==0?"VELOCITY CURVE":"NOTE CURVE",4,0,getWidth()-8,14,Justification::centredLeft);g.setColour(nd::colour(Colour(0xff8ba0ae)));}
 void mouseDown(const juce::MouseEvent& e)override{if(e.mods.isPopupMenu()){juce::PopupMenu menu;menu.addItem(1,"Linear");menu.addItem(2,"Inverse");menu.addItem(3,"Constant 50%");auto safe=juce::Component::SafePointer<PerformanceCurveCanvas>(this);menu.showMenuAsync(juce::PopupMenu::Options().withTargetComponent(this),[safe](int result){if(safe&&result>0)safe->reset(result-1);});return;}end();editing=true;for(auto* parameter:parameters[kind])parameter->beginChangeGesture();draw(e.position);}
 void mouseDrag(const juce::MouseEvent& e)override{if(editing)draw(e.position);}
 void mouseUp(const juce::MouseEvent&)override{end();}
 void mouseDoubleClick(const juce::MouseEvent& e)override{if(!e.mods.isPopupMenu())reset(0);}
};
class PortamentoCurveCanvas:public juce::Component,public juce::SettableTooltipClient {
 juce::RangedAudioParameter* parameter;float origin=0;bool editing=false;
public:
 PortamentoCurveCanvas(SynthProcessor& p):parameter(p.state.getParameter("portaCurve")){setComponentID("portamento-curve");setTooltip("Drag vertically: portamento curve. Double click: linear pitch glide.");}
 ~PortamentoCurveCanvas()override{if(editing)parameter->endChangeGesture();}
 void paint(juce::Graphics& g)override{auto r=getLocalBounds().toFloat().reduced(2);UiStyle::plot(g,r);juce::Path path;float curve=parameter->convertFrom0to1(parameter->getValue());for(int i=0;i<64;++i){float t=i/63.f,x=r.getX()+t*r.getWidth(),y=r.getBottom()-portamentoShape(t,curve)*r.getHeight();if(i==0)path.startNewSubPath(x,y);else path.lineTo(x,y);}g.setColour(UiStyle::blue());g.strokePath(path,juce::PathStrokeType(1.5f));}
 void mouseDown(const juce::MouseEvent& e)override{if(e.mods.isPopupMenu())return;origin=parameter->getValue();editing=true;parameter->beginChangeGesture();}
 void mouseDrag(const juce::MouseEvent& e)override{if(editing){parameter->setValueNotifyingHost(juce::jlimit(0.f,1.f,origin-e.getDistanceFromDragStartY()/70.f));repaint();}}
 void mouseUp(const juce::MouseEvent&)override{if(editing)parameter->endChangeGesture();editing=false;}
 void mouseDoubleClick(const juce::MouseEvent& e)override{if(!e.mods.isPopupMenu()){parameter->setValueNotifyingHost(.5f);repaint();}}
};
class SynthFxQuickPanel:public juce::Component {
 SynthProcessor& p;juce::OwnedArray<juce::Label> labels;juce::OwnedArray<AutomationSlider> sliders;std::vector<std::unique_ptr<juce::AudioProcessorValueTreeState::SliderAttachment>> links;juce::ComboBox rate;std::unique_ptr<juce::AudioProcessorValueTreeState::ComboBoxAttachment> rateLink;
public:
 SynthFxQuickPanel(SynthProcessor& processor):p(processor){using namespace juce;setSize(340,265);const String ids[]={"drive","chorus","delay","reverb","feedback"},names[]={"DRIVE","CHORUS","DELAY","REVERB","FEEDBACK"};for(int i=0;i<5;++i){auto* label=labels.add(new Label());addAndMakeVisible(label);label->setText(names[i],dontSendNotification);label->setBounds(8,8+i*40,85,30);auto* slider=sliders.add(new AutomationSlider());addAndMakeVisible(slider);slider->setSliderStyle(Slider::LinearHorizontal);slider->setTextBoxStyle(Slider::TextBoxRight,false,60,24);slider->bindAutomation(p.state.getParameter(ids[i]),&p);slider->setBounds(95,8+i*40,237,30);links.push_back(std::make_unique<AudioProcessorValueTreeState::SliderAttachment>(p.state,ids[i],*slider));slider->textFromValueFunction=[](double value){return String(value*100,0)+" %";};slider->valueFromTextFunction=[](const String& value){return value.getDoubleValue()/100;};slider->updateText();}addAndMakeVisible(rate);rate.addItemList(dynamic_cast<AudioParameterChoice*>(p.state.getParameter("delayTime"))->choices,1);rate.setBounds(95,215,237,26);rateLink=std::make_unique<AudioProcessorValueTreeState::ComboBoxAttachment>(p.state,"delayTime",rate);}
 void paint(juce::Graphics& g)override{g.fillAll(UiStyle::surface());g.setColour(UiStyle::blue());g.setFont(juce::FontOptions(10.f));g.drawText("DELAY RATE",8,215,85,26,juce::Justification::centredLeft);}
};
class VoicingToggle:public juce::ToggleButton {
public:
 using juce::ToggleButton::ToggleButton;
 void paintButton(juce::Graphics& g,bool over,bool down)override{using namespace juce;float alpha=isEnabled()?1.f:.38f;auto blue=UiStyle::blue();g.setColour((getToggleState()?blue:nd::colour(Colour(0xff5c7484))).withMultipliedAlpha(alpha));Rectangle<float> box(4,getHeight()*.5f-4,8,8);if(getToggleState())g.fillRect(box);else g.drawRect(box,1.f);g.setColour((over||down?blue:nd::colour(Colour(0xffb5c7d3))).withMultipliedAlpha(alpha));g.setFont(FontOptions(9.f,Font::bold));g.drawText(getButtonText(),getLocalBounds().withTrimmedLeft(18),Justification::centredLeft,false);}
};
class PortamentoPanel:public juce::Component,private juce::Timer {
 SynthProcessor& p;VoicingToggle always{"ALWAYS"},scaled{"SCALED"};AutomationSlider porta;PortamentoCurveCanvas curve;std::unique_ptr<juce::AudioProcessorValueTreeState::ButtonAttachment> alwaysLink,scaledLink;std::unique_ptr<juce::AudioProcessorValueTreeState::SliderAttachment> portaLink;
 void timerCallback()override{curve.repaint();}
public:
 PortamentoPanel(SynthProcessor& processor):p(processor),curve(p){using namespace juce;setComponentID("portamento-panel");for(auto* child:std::array<Component*,4>{&always,&scaled,&porta,&curve})addAndMakeVisible(child);always.setBounds(4,0,98,20);scaled.setBounds(108,0,100,20);alwaysLink=std::make_unique<AudioProcessorValueTreeState::ButtonAttachment>(p.state,"portaAlways",always);scaledLink=std::make_unique<AudioProcessorValueTreeState::ButtonAttachment>(p.state,"portaScaled",scaled);porta.setSliderStyle(Slider::RotaryHorizontalVerticalDrag);porta.setTextBoxStyle(Slider::TextBoxBelow,false,65,14);porta.bindAutomation(p.state.getParameter("glide"),&p);porta.setBounds(11,20,78,48);portaLink=std::make_unique<AudioProcessorValueTreeState::SliderAttachment>(p.state,"glide",porta);porta.textFromValueFunction=[](double value){return String(value*1000,0)+" ms";};porta.valueFromTextFunction=[](const String& value){return value.getDoubleValue()/1000;};porta.setDoubleClickReturnValue(true,0);porta.updateText();curve.setBounds(128,27,64,36);startTimerHz(25);}
 ~PortamentoPanel()override{stopTimer();}
 void paint(juce::Graphics& g)override{using namespace juce;UiStyle::card(g,getLocalBounds().toFloat());g.setFont(FontOptions(9.f,Font::bold));g.setColour(nd::colour(Colour(0xff8ba0ae)));g.drawText("PORTA",11,69,78,11,Justification::centred);g.drawText("CURVE",126,69,68,11,Justification::centred);}
};
class VoicingPanel:public juce::Component,private juce::Timer {
 SynthProcessor& p;PerformanceCurveCanvas mapping;std::array<juce::TextButton,2> tabs;std::array<std::unique_ptr<LiveSourceHandle>,2> handles;VoicingToggle mono{"MONO"},legato{"LEGATO"};AutomationSlider poly;juce::TextButton more{"..."};std::vector<std::unique_ptr<juce::AudioProcessorValueTreeState::ButtonAttachment>> buttons;std::vector<std::unique_ptr<juce::AudioProcessorValueTreeState::SliderAttachment>> sliders;
 void select(int kind){mapping.setKind(kind);for(int i=0;i<2;++i)tabs[i].setToggleState(kind==i,juce::dontSendNotification);}
 void timerCallback()override{legato.setEnabled(p.value("mono")>.5f);mapping.repaint();for(auto& handle:handles)handle->repaint();repaint();}
public:
 std::function<void()> onImportInfo;
 VoicingPanel(SynthProcessor& processor):p(processor),mapping(p){using namespace juce;setComponentID("voicing-panel");for(int i=0;i<2;++i){addAndMakeVisible(tabs[i]);tabs[i].setButtonText(i==0?"VELO":"NOTE");tabs[i].getProperties().set("roundedModTab",true);tabs[i].setColour(TextButton::textColourOnId,UiStyle::blue());tabs[i].setColour(TextButton::textColourOffId,nd::colour(Colour(0xff8ba0ae)));tabs[i].getProperties().set("sourceRingSpace",true);tabs[i].setBounds(i*109,0,105,28);tabs[i].onClick=[this,i]{select(i);};handles[i]=std::make_unique<LiveSourceHandle>(p,i+11);addAndMakeVisible(*handles[i]);handles[i]->setBounds(i*109+85,4,18,20);handles[i]->onSelect=[this,i]{select(i);};}addAndMakeVisible(mapping);mapping.setBounds(0,28,214,133);int index=0;for(auto* button:{&mono,&legato}){addAndMakeVisible(*button);const String ids[]={"mono","legato"};buttons.push_back(std::make_unique<AudioProcessorValueTreeState::ButtonAttachment>(p.state,ids[index++],*button));button->setColour(ToggleButton::textColourId,nd::colour(Colour(0xffb5c7d3)));}mono.setBounds(4,183,90,26);legato.setBounds(4,215,97,26);addAndMakeVisible(poly);poly.setSliderStyle(Slider::LinearBar);poly.textFromValueFunction=[](double value){return String((int)std::round(value));};poly.setTextBoxStyle(Slider::TextBoxLeft,false,53,21);poly.setBounds(151,186,54,21);poly.bindAutomation(p.state.getParameter("polyphony"),&p);sliders.push_back(std::make_unique<AudioProcessorValueTreeState::SliderAttachment>(p.state,"polyphony",poly));poly.textFromValueFunction=[](double value){return String((int)std::round(value));};poly.valueFromTextFunction=[](const String& value){return value.getDoubleValue();};poly.setDoubleClickReturnValue(true,12);poly.updateText();addAndMakeVisible(more);more.setBounds(178,163,28,18);more.setTooltip("Synth FX controls / arpeggiator / import information");more.onClick=[this]{PopupMenu menu;menu.addItem(1,"Synth FX controls...");menu.addItem(2,"Arpeggiator",true,p.sequenceArpEnabled());menu.addItem(3,"Import information");auto safe=Component::SafePointer<VoicingPanel>(this);menu.showMenuAsync(PopupMenu::Options().withTargetComponent(&more),[safe](int result){if(!safe)return;if(result==1)CallOutBox::launchAsynchronously(std::make_unique<SynthFxQuickPanel>(safe->p),safe->more.getScreenBounds(),nullptr);if(result==2)safe->p.setSequenceArpEnabled(!safe->p.sequenceArpEnabled());if(result==3&&safe->onImportInfo)safe->onImportInfo();});};select(0);startTimerHz(25);}
 void paint(juce::Graphics& g)override{using namespace juce;g.fillAll(UiStyle::surface());g.setColour(UiStyle::canvas());g.fillRect(0,0,getWidth(),28);g.setColour(UiStyle::headerColour());g.fillRect(0,161,getWidth(),22);g.setColour(nd::colour(Colour(0xff344650)));g.drawHorizontalLine(182,0.f,(float)getWidth());auto text=[&](String name,Rectangle<int> r,Colour colour){g.setColour(colour);g.setFont(FontOptions(9.f,Font::bold));g.drawText(name,r,Justification::centred);};text("VOICING",{8,162,90,20},UiStyle::blue());text("POLY",{103,186,44,21},nd::colour(Colour(0xff8ba0ae)));text(String(p.activeVoices.load())+" / "+String((int)p.value("polyphony")),{111,215,94,26},nd::colour(Colour(0xff9eb1c0)));}
};
